/* ============================================================
 * 本地 iconify-icon 轻量实现
 * 用 assets/vendor/icons-data.js 中的 SVG 数据渲染 <iconify-icon>，
 * 不访问任何外部 API，保证 file:// 直接打开也能瞬间显示图标。
 * 用法与官方一致：<iconify-icon icon="mdi:home" width="24"></iconify-icon>
 * 动态修改 icon 属性时会自动重绘。
 * ============================================================ */
(function () {
    'use strict';
    var ICONS = window.__ICONS__ || {};

    function render(el) {
        var name = el.getAttribute('icon');
        if (!name || !ICONS[name]) {
            el.textContent = '';
            return;
        }
        var data = ICONS[name];
        var w = el.getAttribute('width') || data.w || 24;
        var h = el.getAttribute('height') || data.h || 24;
        var wpx = /^\d+$/.test(w) ? w + 'px' : w;
        var hpx = /^\d+$/.test(h) ? h + 'px' : h;
        var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="' + wpx + '" height="' + hpx +
            '" viewBox="0 0 ' + data.w + ' ' + data.h + '" fill="none" ' +
            'style="display:inline-block;vertical-align:middle;flex:none">' + data.body + '</svg>';
        if (el._lastSVG !== svg) {
            el.innerHTML = svg;
            el._lastSVG = svg;
        }
    }

    if (!window.customElements.get('iconify-icon')) {
        window.customElements.define('iconify-icon', class extends HTMLElement {
            static get observedAttributes() { return ['icon', 'width', 'height']; }
            connectedCallback() { render(this); }
            attributeChangedCallback() { if (this.isConnected) render(this); }
        });
    }

    window.refreshIconify = function (root) {
        (root || document).querySelectorAll('iconify-icon').forEach(render);
    };
})();
